\title{Information-Theoretic Security of BB84: The $\sim$11\% QBER Threshold, Privacy Amplification, and Optimal Two-Universal Hashing}
\author{Aristotle}
\date{June 23, 2026}

\begin{document}
\begin{abstract}
We present a self-contained, formally verified development of the information-theoretic core of the BB84 quantum key distribution protocol. We prove that the canonical intercept--resend attack induces a quantum bit error rate (QBER) of exactly $1/4$, independent of basis. Defining the one-way Shor--Preskill secret-key rate $r(Q)=1-2H_2(Q)$, we prove it strictly decreasing on $[0,1/2]$, vanishing at a \emph{unique} critical QBER $p^\star$, and bracket $p^\star\in(1/16,1/8)$ --- straddling the textbook $\approx 11\%$ --- via two \emph{integer} inequalities ($7^7<2^{20}$ and $2^{56}<15^{15}$). Since $1/4>p^\star$, full interception is always detectable. For privacy amplification we prove a Cauchy--Schwarz leftover-hash bound converting a collision-probability (min-entropy) guarantee into an exponentially small statistical-distance-to-uniform bound, and we prove the GF(2) inner-product hash family \emph{optimally two-universal}: for distinct inputs exactly half of all seeds collide, with the $k$-bit generalization giving collision probability exactly $2^{-k}$. A pigeonhole result shows no deterministic compression is injective, explaining why privacy amplification must be randomized. All results are machine-checked.
\end{abstract}
\maketitle

\section{Introduction}
Classical key exchange derives security from computational assumptions. Quantum key distribution, introduced by Bennett and Brassard in 1984 (\textbf{BB84}), replaces these with the laws of quantum mechanics: no-cloning and conjugate-basis disturbance. An eavesdropper cannot learn the transmitted bits without introducing detectable errors. After the quantum layer is accounted for, security reduces to three classical facts: a quantifiable attack cost, a sharp QBER threshold, and an exponentially effective privacy-amplification step. We formalize all three. We use the natural-logarithm binary entropy $\bine$, so the bit-valued rate $1-2H_2(Q)$ becomes $\log 2 - 2\,\bine(Q)$; the two share sign and zero.

\section{Definitions}

\begin{definition}[Secret-key rate, \texttt{secureKeyRate}]
The asymptotic one-way BB84 secret-key fraction, in nats, is
\[ \skr(Q) := \log 2 - 2\,\bine(Q). \]
Dividing by $\log 2$ recovers the Shor--Preskill rate $1-2H_2(Q)$ in bits.
\end{definition}

\begin{definition}[Conditional Bob error, \texttt{bobErrorProb}]
For common basis $a$ and Eve's basis $e$,
\[ \texttt{bobErrorProb}(a,e) := \begin{cases} 0 & e=a,\\ 1/2 & e\neq a. \end{cases} \]
\end{definition}

\begin{definition}[Intercept--resend QBER, \texttt{interceptResendQBER}]
\[ \qber(a) := \sum_{e\in\{\mathrm{false},\mathrm{true}\}} \tfrac12\,\texttt{bobErrorProb}(a,e). \]
\end{definition}

\begin{definition}[Bit vectors and inner-product hash]
$\texttt{BitVec2}(n) := \Fin\,n \to \Ztwo$. For seed $a$ and input $x$,
\[ \ih(a,x) := \sum_{i=1}^{n} a_i x_i \in \Ztwo. \]
The standard basis vector $e_j$ has a $1$ at index $j$ and $0$ elsewhere.
\end{definition}

\section{The Intercept--Resend Attack: QBER $=1/4$}

\begin{theorem}[\texttt{interceptResendQBER\_eq}]
For every basis $a$, $\qber(a)=1/4$.
\end{theorem}
\begin{proof}[Proof sketch]
Expand the two-term Boolean sum: the $e=a$ term contributes $0$, the $e\neq a$ term contributes $1/2$, each with weight $1/2$, giving $\tfrac14$. Case analysis on $a$ shows basis-independence.
\end{proof}

\section{Secret-Key Rate and the $\sim$11\% Threshold}

\begin{theorem}[\texttt{secureKeyRate\_pos\_iff}]
$0<\skr(Q)\iff \bine(Q)<\tfrac{\log 2}{2}$.
\end{theorem}
\begin{proof}[Proof sketch]
Linear rearrangement of $\log 2 - 2\,\bine(Q)>0$.
\end{proof}

\begin{theorem}[\texttt{secureKeyRate\_strictAntiOn}]
$\skr$ is strictly decreasing on $[0,1/2]$.
\end{theorem}
\begin{proof}[Proof sketch]
$\skr$ is an orientation-reversing affine function of $\bine$, which is strictly increasing on $[0,1/2]$.
\end{proof}

\begin{lemma}[\texttt{binEntropy\_one\_eighth\_gt}]
$\tfrac{\log 2}{2}<\bine(1/8)$, reducing to $7^7<2^{20}$.
\end{lemma}
\begin{proof}[Proof sketch]
Expanding $\bine(1/8)=\tfrac18\log 8 + \tfrac78\log\tfrac87$ and clearing logarithms reduces the claim to $823543<1048576$.
\end{proof}

\begin{lemma}[\texttt{binEntropy\_one\_sixteenth\_lt}]
$\bine(1/16)<\tfrac{\log 2}{2}$, reducing to $2^{56}<15^{15}$.
\end{lemma}
\begin{proof}[Proof sketch]
Expanding $\bine(1/16)=\tfrac{1}{16}\log 16 + \tfrac{15}{16}\log\tfrac{16}{15}$ and clearing logarithms reduces the claim to $2^{56}<15^{15}$.
\end{proof}

\begin{lemma}[\texttt{binEntropy\_one\_quarter\_gt}]
$\tfrac{\log 2}{2}<\bine(1/4)$.
\end{lemma}
\begin{proof}[Proof sketch]
Expand $\bine(1/4)$ using $\log 4 = 2\log 2$; the comparison reduces to an elementary positivity fact.
\end{proof}

\begin{theorem}[Threshold existence, \texttt{exists\_threshold}]
There exists $p^\star\in(1/16,1/8)=(6.25\%,12.5\%)$ with $\skr(p^\star)=0$.
\end{theorem}
\begin{proof}[Proof sketch]
By the previous lemmas $\bine(1/16)<(\log 2)/2<\bine(1/8)$; continuity of $\bine$ and the Intermediate Value Theorem give a root of $\bine(p)=(\log 2)/2$, i.e. $\skr(p^\star)=0$.
\end{proof}

The exact root of $H_2(p)=1/2$ is $p^\star\approx 0.1100$.

\begin{theorem}[Threshold uniqueness, \texttt{threshold\_unique}]
If $p,q\in[0,1/2]$ both satisfy $\skr=0$, then $p=q$.
\end{theorem}
\begin{proof}[Proof sketch]
A strictly antitone function is injective.
\end{proof}

\begin{theorem}[\texttt{secureKeyRate\_one\_quarter\_neg}]
$\skr(1/4)<0$.
\end{theorem}
\begin{proof}[Proof sketch]
$\bine(1/4)>(\log 2)/2$ gives $2\,\bine(1/4)>\log 2$, so $\skr(1/4)<0$.
\end{proof}

\begin{corollary}[\texttt{interceptResend\_insecure}]
For every $a$, $\skr(\qber(a))<0$.
\end{corollary}
\begin{proof}[Proof sketch]
Substitute $\qber(a)=1/4$ into the previous theorem.
\end{proof}

\begin{corollary}[\texttt{threshold\_lt\_interceptResend}]
For $p\in(1/16,1/8)$ and any $a$, $p<\qber(a)=1/4$.
\end{corollary}

\section{Privacy Amplification}

\begin{theorem}[Leftover-hash core, \texttt{statDist\_le\_collision}]
Let $M>0$ and $p:\Fin\,M\to\mathbb{R}$ with $\sum_i p_i=1$. Then
\[ \sum_{i=1}^{M}\Big|p_i-\tfrac1M\Big| \le \sqrt{\,M\sum_{i=1}^{M}p_i^2-1\,}. \]
\end{theorem}
\begin{proof}[Proof sketch]
Let $d_i=p_i-1/M$; then $\sum_i d_i=0$ and $\sum_i d_i^2=\sum_i p_i^2-1/M$. Cauchy--Schwarz against the all-ones vector gives $\big(\sum_i|d_i|\big)^2\le M\sum_i d_i^2 = M\sum_i p_i^2-1$. Take square roots. Nonnegativity of $p$ is not used.
\end{proof}

\begin{theorem}[Exponential decay, \texttt{privacyAmplification\_exp\_bound}]
Let $M=2^\ell$ and $p:\Fin(2^\ell)\to\mathbb{R}$ with $\sum_i p_i=1$ and $\sum_i p_i^2\le 2^{-k}$. Then
\[ \sum_i \big|p_i-2^{-\ell}\big| \le \sqrt{2^{\,\ell-k}}. \]
\end{theorem}
\begin{proof}[Proof sketch]
Apply the previous theorem with $M=2^\ell$ and bound $\sum_i p_i^2\le 2^{-k}$, dropping $-1$ by monotonicity of $\sqrt{\cdot}$: $\sqrt{2^\ell\cdot 2^{-k}}=\sqrt{2^{\ell-k}}$.
\end{proof}

When the entropy gap $k-\ell>0$ this is $2^{-(k-\ell)/2}$, exponentially small.

\begin{theorem}[Randomization is necessary, \texttt{injective\_extractor\_impossible}]
Let \textup{State}, \textup{Block} be finite, \textup{State} nonempty, $|\textup{Block}|>1$. For any $f:\textup{State}\to\textup{Block}\to\textup{State}$, the map $(s,b)\mapsto f(s,b)$ is not injective.
\end{theorem}
\begin{proof}[Proof sketch]
The domain has cardinality $|\textup{State}|\cdot|\textup{Block}|>|\textup{State}|$, the codomain; pigeonhole forces a collision.
\end{proof}

\section{Optimal Two-Universal Hashing}

The inner-product hash is bilinear over GF(2): $\ih(a,x-y)=\ih(a,x)-\ih(a,y)$ (\texttt{innerHash\_sub}); $\ih(a+b,d)=\ih(a,d)+\ih(b,d)$ (\texttt{innerHash\_add\_left}); $\ih(e_j,d)=d_j$ (\texttt{innerHash\_basis}); $\ih(a+e_j,d)=\ih(a,d)+d_j$ (\texttt{innerHash\_toggle}). A collision is equivalent to $\ih(a,x-y)=0$ (\texttt{collision\_iff}); in characteristic 2, $a+e_j+e_j=a$ (\texttt{add\_e\_add\_e}).

\begin{lemma}[\texttt{card\_zero\_eq\_card\_one}]
If $d_j=1$, the involution $a\mapsto a+e_j$ bijects $\{a:\ih(a,d)=0\}$ with $\{a:\ih(a,d)=1\}$.
\end{lemma}
\begin{proof}[Proof sketch]
Toggling coordinate $j$ adds $d_j=1$, flipping the hash parity; the map is its own inverse.
\end{proof}

\begin{lemma}[\texttt{card\_zero\_add\_card\_one}]
$\#\{a:\ih(a,d)=0\}+\#\{a:\ih(a,d)=1\}=2^n$.
\end{lemma}

\begin{lemma}[\texttt{card\_collision\_eq\_half}]
If $d_j=1$ then $2\,\#\{a:\ih(a,d)=0\}=2^n$.
\end{lemma}

\begin{lemma}[\texttt{sub\_eq\_one\_of\_ne}]
If $x_j\neq y_j$ in $\Ztwo$ then $(x-y)_j=1$.
\end{lemma}

\begin{theorem}[Two-universality, \texttt{two\_universal}]
For distinct $x\neq y$,
\[ 2\cdot\#\{a:\ih(a,x)=\ih(a,y)\}=2^n. \]
\end{theorem}
\begin{proof}[Proof sketch]
$x,y$ differ at some $j$, so $(x-y)_j=1$. By \texttt{collision\_iff} the collision set is $\{a:\ih(a,x-y)=0\}$, whose doubled cardinality is $2^n$.
\end{proof}

The collision probability over a uniform seed is exactly $1/2$, the optimum for one output bit.

\begin{theorem}[$k$-row generalization, \texttt{two\_universal\_k}]
For distinct $x\neq y$,
\[ 2^k\cdot\#\{A:\Fin\,k\to\texttt{BitVec2}(n)\mid \forall r,\ \ih(A_r,x)=\ih(A_r,y)\}=(2^n)^k. \]
\end{theorem}
\begin{proof}[Proof sketch]
Row-wise each row collides iff $\ih(A_r,x-y)=0$; the collision matrices form the $k$-fold product of the single-row zero set, and applying the half-counting lemma to each independent row yields $2^k(\#\{\cdots\})^k=(2^n)^k$.
\end{proof}

The collision probability for $k$ output bits is exactly $2^{-k}$.

\section{Synthesis}
The results compose: listening costs error (QBER $1/4$, Thm.~3.1) above the unique threshold $p^\star\approx 11\%$ (Thms.~4.6--4.7), so full interception is always caught (Cor.~4.9); below $p^\star$ the rate is positive (Thm.~4.1); a random GF(2) parity hash is optimally two-universal (Thms.~6.5--6.6), feeding collision probability $2^{-k}$ into the leftover-hash bound (Thm.~5.1) to drive leakage to $2^{-(k-\ell)/2}$ (Thm.~5.2); randomization is mandatory (Thm.~5.3). No step uses a computational hardness assumption.

\section{Future Directions}
\begin{itemize}
\item \textbf{Rational tightening of $p^\star$} to width $<10^{-3}$ via nested integer power comparisons.
\item \textbf{Two-way post-processing}: $r_2(Q)=1+\log_2(1-2Q(1-Q))-H_2(Q)$ to certify the $\approx 20\%$ threshold.
\item \textbf{Full leftover-hash regime}: extend \texttt{two\_universal} to random $A\in(\Ztwo)^{\ell\times n}$ with collision probability exactly $2^{-\ell}$.
\end{itemize}

\section*{References}
\begin{thebibliography}{9}
\bibitem{BB84} C.~H.~Bennett and G.~Brassard, \emph{Quantum cryptography: Public key distribution and coin tossing}, Proc. IEEE Int. Conf. Computers, Systems and Signal Processing, 1984.
\bibitem{ShorPreskill} P.~W.~Shor and J.~Preskill, \emph{Simple proof of security of the BB84 quantum key distribution protocol}, Phys. Rev. Lett. \textbf{85} (2000), 441--444.
\bibitem{ILL} R.~Impagliazzo, L.~A.~Levin, and M.~Luby, \emph{Pseudo-random generation from one-way functions}, STOC 1989. (Leftover Hash Lemma.)
\end{thebibliography}

