import math
from typing import Tuple

def bin_entropy_nats(q: float) -> float:
    if q <= 0.0 or q >= 1.0:
        return 0.0
    return -q * math.log(q) - (1.0 - q) * math.log(1.0 - q)

def secure_key_rate(q: float) -> float:
    return math.log(2.0) - 2.0 * bin_entropy_nats(q)

def find_threshold(lo: float = 1/16, hi: float = 1/8, iters: int = 200) -> float:
    assert secure_key_rate(lo) > 0 > secure_key_rate(hi)
    for _ in range(iters):
        mid = 0.5 * (lo + hi)
        if secure_key_rate(mid) > 0: lo = mid
        else: hi = mid
    return 0.5 * (lo + hi)

def certify() -> Tuple[bool, bool]:
    return (7**7 < 2**20, 2**56 < 15**15)

if __name__ == "__main__":
    p = find_threshold()
    print(f"p* = {p:.6f} ({100*p:.3f}%), in (1/16,1/8): {1/16 < p < 1/8}")
    print(f"secureKeyRate(p*) = {secure_key_rate(p):.2e}")
    print(f"integer certificates (7^7<2^20, 2^56<15^15): {certify()}")

import math

def bin_entropy_nats(q: float) -> float:
    if q <= 0.0 or q >= 1.0: return 0.0
    return -q*math.log(q) - (1-q)*math.log(1-q)

def secure_key_rate(q: float) -> float:
    return math.log(2.0) - 2.0*bin_entropy_nats(q)

def bob_error_prob(alice: bool, eve: bool) -> float:
    return 0.0 if eve == alice else 0.5

def intercept_resend_qber(alice: bool) -> float:
    return sum(0.5 * bob_error_prob(alice, e) for e in (False, True))

if __name__ == "__main__":
    for a in (False, True):
        q = intercept_resend_qber(a)
        print(f"basis={a}: QBER={q:.4f}, secureKeyRate={secure_key_rate(q):.4f}")
    assert all(abs(intercept_resend_qber(a) - 0.25) < 1e-12 for a in (False, True))
    assert secure_key_rate(0.25) < 0
    print("Full intercept-resend (25%) is above threshold and detectable.")

import itertools
from typing import Tuple

def inner_hash(a: Tuple[int, ...], x: Tuple[int, ...]) -> int:
    return sum(ai*xi for ai, xi in zip(a, x)) % 2

def count_colliding_seeds(n: int, x, y) -> int:
    return sum(1 for a in itertools.product((0,1), repeat=n)
               if inner_hash(a, x) == inner_hash(a, y))

if __name__ == "__main__":
    for n in range(1, 7):
        x = tuple([0]*n); y = tuple([1] + [0]*(n-1))
        c = count_colliding_seeds(n, x, y)
        assert 2*c == 2**n
        print(f"n={n}: 2*#collisions={2*c} = 2^n={2**n}, prob={c/2**n:.3f}")
    # k-row product
    n = 4; x = tuple([0]*n); y = tuple([1]+[0]*(n-1))
    rows = sum(1 for a in itertools.product((0,1), repeat=n)
               if inner_hash(a, x) == inner_hash(a, y))
    for k in range(1, 5):
        assert 2**k * rows**k == (2**n)**k
        print(f"k={k}: collision prob = 2^-{k} = {2.0**-k}")

import math
from typing import List

def stat_dist(p: List[float]) -> float:
    m = len(p); return sum(abs(pi - 1.0/m) for pi in p)

def collision_bound(p: List[float]) -> float:
    m = len(p); return math.sqrt(max(m*sum(pi*pi for pi in p) - 1.0, 0.0))

def pa_bound(ell: int, k: int) -> float:
    return math.sqrt(2.0**(ell - k))

if __name__ == "__main__":
    for name, p in [("near-uniform", [.3,.25,.25,.2]),
                    ("spiked", [.7,.1,.1,.1]),
                    ("point-mass", [1.,0.,0.,0.])]:
        lhs, rhs = stat_dist(p), collision_bound(p)
        assert lhs <= rhs + 1e-9
        print(f"{name:>12}: {lhs:.4f} <= {rhs:.4f}")
    for k in range(8, 40, 8):
        print(f"ell=8, k={k}: leakage <= {pa_bound(8, k):.3e}")

