    # binEntropy(a/b) < (log2)/2  <=>  a^a * (b-a)^(b-a) < 2^(...)
    lhs <- a^a * (b-a)^(b-a)
    rhs <- 2^(b - <correction>)            # exponent from clearing logs
    return (lhs < rhs)                     # True => below threshold (secure)

function LOCATE_THRESHOLD(lo, hi):
    assert CERTIFY_BRACKET secures lo and breaks hi   # sign change
    # IVT guarantees a unique root p* in (lo, hi)
    return bisection on secureKeyRate within (lo, hi)

